import z3

n = 14
# We'll use boolean variables for edges
# edge variables e_{i,j} for 0 <= i < j < n
edges = {}
for i in range(n):
    for j in range(i+1, n):
        edges[(i,j)] = z3.Bool(f"e_{i}_{j}")

s = z3.Solver()

# At least 18 edges
edge_vars = list(edges.values())
s.add(z3.Sum([z3.If(v, 1, 0) for v in edge_vars]) >= 18)

# 3-colorability: we can assign each vertex a color (0,1,2)
colors = [z3.Int(f"c_{i}") for i in range(n)]
for i in range(n):
    s.add(colors[i] >= 0, colors[i] <= 2)
for (i,j), v in edges.items():
    s.add(z3.Implies(v, colors[i] != colors[j]))

# Girth >= 7: no cycles of length 3,4,5,6
# For each cycle length L, we need to forbid all possible L-cycles
import itertools

def forbid_cycle(vars):
    # At least one edge in the cycle must be absent
    s.add(z3.Not(z3.And(vars)))

# Length 3: triangles
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            forbid_cycle([edges[(i,j)], edges[(j,k)], edges[(i,k)]])

# Length 4
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            for l in range(k+1, n):
                # cycles of 4 distinct vertices (i,j,k,l)
                # possible orderings: i-j-k-l-i, i-j-l-k-i, i-k-j-l-i
                # Actually all 3 distinct 4-cycles on 4 vertices
                # Cycle forms: edges (i,j),(j,k),(k,l),(l,i)
                # Also (i,j),(j,l),(l,k),(k,i)
                # And (i,k),(k,j),(j,l),(l,i)
                cycles = [
                    [(i,j),(j,k),(k,l),(i,l)],
                    [(i,j),(j,l),(k,l),(i,k)],
                    [(i,k),(j,k),(j,l),(i,l)]
                ]
                for cyc in cycles:
                    forbid_cycle([edges[e] for e in cyc])

# Length 5
for combo in itertools.combinations(range(n), 5):
    vertex_list = list(combo)
    # There are 12 distinct 5-cycles on 5 labeled vertices (up to isomorphism, but we need all)
    # Actually number of distinct Hamiltonian cycles on 5 vertices: (5-1)! / 2 = 12
    # We can generate all permutations of the 5 vertices and treat as cycle order
    # But we need to avoid duplicates (reversals and rotations)
    # Simpler: generate all edges and check if they form a cycle?
    # Let's just iterate over all permutations of 5 vertices and check cycle edges
    # But that could be heavy: C(14,5)*12 = 2002*12 = 24024, okay
    import itertools as it
    for perm in it.permutations(vertex_list):
        # perm = (v0,v1,v2,v3,v4) cycle: v0-v1-v2-v3-v4-v0
        cyc_edges = [(perm[0], perm[1]), (perm[1], perm[2]), (perm[2], perm[3]), (perm[3], perm[4]), (perm[4], perm[0])]
        # Normalize to canonical order (each edge sorted)
        normalized = []
        for (a,b) in cyc_edges:
            if a < b:
                normalized.append((a,b))
            else:
                normalized.append((b,a))
        forbid_cycle([edges[e] for e in normalized])

# Length 6
for combo in itertools.combinations(range(n), 6):
    vertex_list = list(combo)
    # Number of distinct 6-cycles: (6-1)! / 2 = 60
    # C(14,6) = 3003, 3003*60 = 180180, might be heavy but okay
    for perm in it.permutations(vertex_list):
        cyc_edges = [(perm[i], perm[(i+1)%6]) for i in range(6)]
        normalized = []
        for (a,b) in cyc_edges:
            if a < b:
                normalized.append((a,b))
            else:
                normalized.append((b,a))
        forbid_cycle([edges[e] for e in normalized])

print("Number of constraints added. Solving...")
result = s.check()
print("Result:", result)
if result == z3.sat:
    m = s.model()
    edge_list = []
    for (i,j), v in edges.items():
        if m.eval(v):
            edge_list.append((i,j))
    print("Edges:", edge_list)
    print("Number of edges:", len(edge_list))
else:
    print("UNSAT")

