import itertools
from pysat import SATSolver
from pysat.card import CardEnc

n = 14
# Map each edge (i,j) with i<j to a variable ID
edge_var = {}
var_id = 1
for i in range(n):
    for j in range(i+1, n):
        edge_var[(i,j)] = var_id
        var_id += 1

print("Total edge variables:", var_id-1)

s = SATSolver()

# At least 18 edges
lits = list(edge_var.values())
s.add_clauses(CardEnc.atleast(lits, 18))

# No cycles of length 3
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            # forbid all three edges present
            s.add_clause([-edge_var[(i,j)], -edge_var[(j,k)], -edge_var[(i,k)]])

print("Added triangle constraints")

# No cycles of length 4
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            for l in range(k+1, n):
                cycles = [
                    [(i,j),(j,k),(k,l),(i,l)],
                    [(i,j),(j,l),(k,l),(i,k)],
                    [(i,k),(j,k),(j,l),(i,l)]
                ]
                for cyc in cycles:
                    s.add_clause([-edge_var[e] for e in cyc])

print("Added C4 constraints")

# No cycles of length 5
for combo in itertools.combinations(range(n), 5):
    verts = list(combo)
    for perm in itertools.permutations(verts):
        cyc_edges = [(perm[i], perm[(i+1)%5]) for i in range(5)]
        normalized = []
        for (a,b) in cyc_edges:
            if a < b:
                normalized.append((a,b))
            else:
                normalized.append((b,a))
        s.add_clause([-edge_var[e] for e in normalized])

print("Added C5 constraints")

# No cycles of length 6
for combo in itertools.combinations(range(n), 6):
    verts = list(combo)
    for perm in itertools.permutations(verts):
        cyc_edges = [(perm[i], perm[(i+1)%6]) for i in range(6)]
        normalized = []
        for (a,b) in cyc_edges:
            if a < b:
                normalized.append((a,b))
            else:
                normalized.append((b,a))
        s.add_clause([-edge_var[e] for e in normalized])

print("Added C6 constraints")
print("Solving...")
result = s.solve()
print("Result:", result)
if result:
    model = s.get_model()
    edges_present = []
    for (i,j), v in edge_var.items():
        if v in model:
            edges_present.append((i,j))
    print("Edges:", edges_present)
    print("Count:", len(edges_present))
else:
    print("UNSAT")
